WITH valid AS (SELECT *, CAST(balance AS INT) AS balance_int FROM accounts WHERE opened_date > DATE '2023-08-26' AND balance <= 38000), matched AS (SELECT a.*, sub.id AS subscription_id, sub.plan, sub.monthly_fee FROM valid a INNER JOIN subscriptions sub ON a.customer_id = sub.customer_id AND a.opened_date >= sub.start_date AND a.opened_date <= DATE_ADD(sub.end_date, 10)), with_windows AS (SELECT id, customer_id, account_type, balance, subscription_id, MIN(monthly_fee) OVER (PARTITION BY status, plan ORDER BY balance_int, id, subscription_id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS last7_min_monthly_fee, AVG(monthly_fee) OVER (PARTITION BY status, plan ORDER BY balance_int, id, subscription_id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS last7_avg_monthly_fee, SUM(monthly_fee) OVER (PARTITION BY status, plan ORDER BY balance_int, id, subscription_id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS last7_sum_monthly_fee, RANK() OVER (PARTITION BY account_type ORDER BY monthly_fee DESC NULLS LAST) AS monthly_fee_rank FROM matched WHERE subscription_id < 5), joined AS (SELECT a.*, b.name, b.age FROM with_windows a LEFT JOIN customers b ON a.customer_id = b.id) SELECT customer_id, ROUND(SUM(subscription_id) / NULLIF(COUNT(CASE WHEN account_type = 'CHECKING' THEN 1 END), 0), 2) AS subscription_id_per_checking, SUM(subscription_id) FILTER (WHERE account_type = 'SAVINGS') AS savings_total_subscription_id FROM joined GROUP BY 1 ORDER BY savings_total_subscription_id DESC;
